<h2>Calculate sales commission with an accelerator</h2><p class="lead">Estimate commission using a base rate up to a threshold and an accelerator rate above it.</p><div class="notice">Use the signed compensation plan as the authority. This calculator assumes the accelerator applies only to revenue above the threshold, not retroactively to all sales.</div><div class="form-grid"><div class="field"><label for="sales">Commissionable sales / bookings</label><input id="sales" type="number" value="1200000" min="0" step="any"></div><div class="field"><label for="rate">Base commission rate (%)</label><input id="rate" type="number" value="5" min="0" step="any"></div><div class="field"><label for="threshold">Accelerator threshold</label><input id="threshold" type="number" value="1000000" min="0" step="any"></div><div class="field"><label for="accel">Rate above threshold (%)</label><input id="accel" type="number" value="8" min="0" step="any"></div><div class="field"><label for="draw">Recoverable/nonrecoverable draw to subtract</label><input id="draw" type="number" value="0" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Gross commission</span><strong id="commission">—</strong></div><div class="metric"><span>Base-tier commission</span><strong id="base">—</strong></div><div class="metric"><span>Accelerated-tier commission</span><strong id="accelerated">—</strong></div><div class="metric"><span>Commission after entered draw</span><strong id="net">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('commission').textContent='—';$('base').textContent='—';$('accelerated').textContent='—';$('net').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const s=num('sales'),r=num('rate')/100,t=num('threshold'),a=num('accel')/100,d=num('draw');if(!(s>=0&&r>=0&&t>=0&&a>=0&&d>=0))throw 0;const base=Math.min(s,t)*r,extra=Math.max(0,s-t)*a,g=base+extra;$('commission').textContent=fmt(g,2);$('base').textContent=fmt(base,2);$('accelerated').textContent=fmt(extra,2);$('net').textContent=fmt(Math.max(0,g-d),2);$('note').textContent='Commission plans can use quotas, cumulative tiers, cliffs, caps, splits, collection rules and product multipliers. This models one simple marginal accelerator.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
